/**
 * SystemLab — Logos de marques réelles (chemins SVG 24×24).
 *
 * Source : simple-icons (licence CC0), extraits statiquement à la génération
 * pour ne pas embarquer les ~10 Mo du paquet côté client. Chaque entrée
 * associe un composant du catalogue (ou une entreprise de la galerie) à son
 * logo monochrome et à sa couleur officielle.
 *
 * `darkMode` : la couleur officielle peut être illisible sur un fond nuit
 * (noir pur : Kafka, X, Uber → inversion ; couleur sombre : Elasticsearch,
 * OpenSearch → éclaircissement).
 */

export interface BrandLogo {
  /** Nom lisible de la marque (aria, infobulle) */
  title: string;
  /** Couleur officielle de la marque (hex) */
  color: string;
  /** Chemin SVG (viewBox 0 0 24 24, remplissage plein) */
  path: string;
  /** Stratégie de thème sombre : les logos noirs (X, Uber, Kafka…) sont
   *  inversés (le filtre brightness ne peut pas éclaircir le noir pur), les
   *  couleurs sombres (Elasticsearch…) sont simplement éclaircies. */
  darkMode?: "invert" | "brighten" | "none";
}

