/** Logo de marque d'un composant du catalogue (undefined → icône Lucide). */
export function getComponentLogo(componentId: string | undefined): BrandLogo | undefined {
  if (!componentId) return undefined;
  return COMPONENT_LOGOS[componentId];
}

/** Logo d'une entreprise de la galerie (undefined → repli générique). */
export function getCompanyLogo(key: string | undefined): BrandLogo | undefined {
  if (!key) return undefined;
  return COMPANY_LOGOS[key];
}
